style.css:
/* 全局文字渲染优化 - 保留原粗细版 */
*:not(i):not([class*="icon"]) {
    /* 1. 去掉了 font-weight: 400 !important; 
       现在标题和加粗文字会正常显示，不会被迫变细 */

    /* 2. 阴影渲染核心 */
    /* 使用 rgba(0,0,0,0.2) 模拟原本 #999999 的效果，但支持深色模式不发白 */
    text-shadow: 0.1px 0.1px 1px rgba(0, 0, 0, 0.2) !important;

    /* 3. 开启抗锯齿 */
    /* 这一步必不可少，否则默认渲染加上阴影后，文字会显得脏兮兮且过于粗重 */
    -webkit-font-smoothing: antialiased !important;
    -moz-osx-font-smoothing: grayscale !important;
}
